      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n8~9월 중 일정 협의)30분3만) Zoom 또는 전화 인터뷰 -패션 브랜드 근무자 좌담회-50대 이상 남녀\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.08.20. 10:14\n조회 63\n구독\n8~9월 중 일정 협의)30분3만) Zoom 또는 전화 인터뷰 -패션 브랜드 근무자 좌담회-50대 이상 남녀\n[모집대상]\n1. 패션 브랜드 본사 회계·재무·경영지원·IT 등 관련 부서 근무자\n- 매장 POS, ERP, 카드결제 및 매출·정산 시스템의 도입·운영·관리 경험이 있는 분\n- 현재 또는 과거에 POS와 ERP를 별도로 운영하는 환경을 경험해 본 분\n- 택스프리(Tax Free) 운영 또는 정산 경험이 있는 분\n2. 온라인 인터뷰 참여가 가능한 분\n- Zoom 또는 전화 인터뷰 참여 가능자\n[조사안내]\n1. 방식: Zoom 또는 전화 인터뷰\n2. 소요 시간: 약 30분\n3. 일정: 2026년 8~9월 중 일정 협의\n4. 사례금: 30,000원\n- 인터뷰를 최종 완료하신 분께 계좌이체로 지급드립니다.\n[주요질문]\n- 회사에서 POS와 ERP를 별도로 운영하는 이유와 배경\n- POS와 ERP에서 각각 어떤 업무와 데이터를 관리하는지\n- 매장 결제부터 매출 집계·정산까지 데이터가 어떤 시스템을 거쳐 처리되는지\n- 카드결제, 택스프리 등 결제 환경을 어떻게 구성하고 관리하는지\n- POS와 ERP를 별도로 운영하면서 발생하는 관리상의 불편이나 비효율\n- 신규 POS·ERP 또는 결제 시스템 도입 시 본사에서 중요하게 고려하는 요소\nhttps://forms.gle/ReYnoCgxbWgK1vkX8\n8~9월 중 일정 협의)30분3만) Zoom 또는 전화 인터뷰 -패션 브랜드 근무자 좌담회\n010-4648-7146 -- 연락처 사이 하이픈 꼭 챙겨주시구요^^ 하이픈 안챙기시는 분 연락처에 숫자가 한개씩 누락되어서 숫자10개가 옵니다ㅠㅠ 연락처 적으신 후 숫자 11개 모두 적었는지 확인 부탁드립니다^^ 간혹 남의번호 적는분이 계십니다,그사람 아닌데요 하면,굉장히 민망하지요ㅠ 적고나서 확인부탁드립니다~ 해당없는 칸에는 해당없음 또는 점 . 또는 무 로 적어주세요~\nforms.gle\n좋아요\n0\n송파구 이웃은 지금 어떤 이야기 중일까?\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.08.20. 10:37 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n8/31) 만55~69세 남녀] 골프 좌담회\n좌담회알바좌담회카페\n26.08.20.\n댓글\n0\n8~9월 중 일정 협의)30분3만) Zoom 또는 전화 인터뷰 -패션 브랜드 근무자 좌담회-50대 이상 남녀\n좌담회알바좌담회카페\n26.08.20.\n댓글\n1\n8~9월 중 일정 협의)30분3만) Zoom 또는 전화 인터뷰 -패션 브랜드 근무자 좌담회-40대 남녀\n좌담회알바좌담회카페\n26.08.20.\n댓글\n1\n8~9월 중 일정 협의)30분3만) Zoom 또는 전화 인터뷰 -패션 브랜드 근무자 좌담회-30대 남녀\n좌담회알바좌담회카페\n26.08.20.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
