      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n9/15~16) 여성(20-29세)-스킨케어 제품유치 후 대면 좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.08.20. 16:36\n조회 98\n구독\n9/15~16) 남성(20-39세)/여성(20-29세)-스킨케어 제품유치 후 대면 좌담회\n안녕하세요! 좌담회 회사입니다.\n스킨케어 제품 유치 후 ( 간단한 온라인 설문) 대면 좌담회가 있습니다.\n잘 읽어보시고 조사 참여 가능하신 분 신청 부탁드립니다.\n<공통 조건>\n20-39세 남성/여성\n다양한 제품의 스킨케어와 바디케어 제품을 사용하는분\n1차 방문 : 제품픽업차 방문 + 2차 방문 : 대면 좌담회\n1차,2차 방문이 모두 가능하신 분\n<일정>\n- 유치 제품 픽업 장소 : 강남구청역 인근\n- 유치 제품 픽업 일자 : 추후 안내\n- 좌담회 일정 : 9/15(화) - 9/16(수)\n여성그룹 1:30 -3:30\n남성그룹 5:00- 7:00\n- 좌담회 장소 : 강남구청역 인근 도보 6분\n- 사례비 : 7 만원\n< 신청시 기재 사항 > *** 최대한 자세히 기재해 주세요***\n1. 이름/ 성별/ 나이(주민번호앞자리)/ 거주구/ 연락처/ 결혼여부/직업(직장명)\n2 . 피부타입 (건성, 중성, 복합성, 지성, 수분지 등)\n3. 정기적으로 사용하고 있는 스킨케어 제품의 브랜드 모두 기재 (클렌징 폼/ 폼 클렌저 , 미스트, 토너, 에멀전, 아이케어, 에센스 세럼 앰플, 수분크림, 자외선차단제 )\n4. 정기적으로 사용하고 있는 바디 세정제 브랜드 ( 바디 클렌저, 바디워시)\n5. 정기적으로 사용하고 있는 바디 보습제 브랜드 (바디크림, 바디 로션)\n6. 통화 가능한 시간\nhttps://forms.gle/dK5Gc8DMLyupdvoW6\n9/15~16) 남성(20-39세)/여성(20-29세)-스킨케어 제품유치 후 대면 좌담회\n010-4648-7146 -- 연락처 사이 하이픈 꼭 챙겨주시구요^^ 하이픈 안챙기시는 분 연락처에 숫자가 한개씩 누락되어서 숫자10개가 옵니다ㅠㅠ 연락처 적으신 후 숫자 11개 모두 적었는지 확인 부탁드립니다^^ 간혹 남의번호 적는분이 계십니다,그사람 아닌데요 하면,굉장히 민망하지요ㅠ 적고나서 확인부탁드립니다~ 해당없는 칸에는 해당없음 또는 점 . 또는 무 로 적어주세요~\nforms.gle\n좋아요\n0\n송파구에서 많이 본 동네소식 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n9/9~10) 20-60대 남성 ) 최근 6개월 이내, 상급종합병원에서 입/퇴원을 경험한 환자 및 보호자 대상의 좌담회\n좌담회알바좌담회카페\n26.08.20.\n댓글\n0\n9/15~16) 여성(20-29세)-스킨케어 제품유치 후 대면 좌담회\n좌담회알바좌담회카페\n26.08.20.\n댓글\n0\n9/15~16) 남성(20-39세)-스킨케어 제품유치 후 대면 좌담회\n좌담회알바좌담회카페\n26.08.20.\n댓글\n0\n8/24~28일중 )LG 식기세척기 14인용 구독자 가구방문 인터뷰 대상 20-50대 여자 식기세척기 가구방문 인터뷰 희망자 모집\n좌담회알바좌담회카페\n26.08.20.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
