      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n고유링크)9/7~11) 만 30-39세 서울거주 여성-주방용 소형 가전 집방문 인터뷰\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.08.20. 23:43\n조회 16\n구독\n고유링크) 9/7~11) 만 30-39세 서울거주 여성-주방용 소형 가전 집방문 인터뷰\n고유링크) 9/7~11) 만 30-55세 서울거주 여성-주방용 소형 가전 집방문 인터뷰\n모집이 마감되면 링크가 열리지 않으니 참고 부탁드립니다 ~\n참여조건\n[보내드리는 에어프라이어 제품을 사용 후 다이어리를 작성 하고, 추후에 연구원이 집에 방문하여 함께 이야기 나누는 인터뷰입니다.]\n조사 대상:\n1. 만 30-55세 서울 거주 여성\n2. 20평 이상의 아파트에서 거주하고, 요리에 관심이 많은 응답자\n3. 향후 1년 이내 20만원 이상의 에어프라이어 또는 주방 용품 제품 구입 의향 있는 자\n★ 집방문 인터뷰 참여 전 보내드리는 제품을 1주일 사용하며 다이어리를 작성해주셔야 합니다.\n★ 인터뷰 종료 후 1주일이내 사용하신 제품은 반납해주셔야 합니다.\n조사장소 응답자의 집\n조사기간 2026-09-07 ~ 2026-09-11일중 하루/ 시간은 추후 안내드립니다\n소요시간 2시간\n사례비 세전 300,000원\n조사방법 2시간 집방문 인터뷰\n안내사항 1주일 동안 보내드리는 제품을 직접 사용해보고, 다이어리를 작성해 주신 후 집방문 인터뷰까지 완료해주셔야 합니다.\n조사 참여 고유링크\nhttps://www.hrc-ms.com/participate/improSurvey/767?refuser=23341&intro=2\n좋아요\n0\n'좋아요'로 마음을 나누세요!\n송파구의 더 많은 인기글 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n고유링크) 9/7~11) 만 50-55세 서울거주 여성-주방용 소형 가전 집방문 인터뷰\n좌담회알바좌담회카페\n26.08.20.\n댓글\n0\n고유링크) 9/7~11) 만 40-49세 서울거주 여성-주방용 소형 가전 집방문 인터뷰\n좌담회알바좌담회카페\n26.08.20.\n댓글\n0\n고유링크)9/7~11) 만 30-39세 서울거주 여성-주방용 소형 가전 집방문 인터뷰\n좌담회알바좌담회카페\n26.08.20.\n댓글\n0\n8/29 ) [0~24개월 자녀를 둔 여성_벌레물림치료제 사용자좌담회]\n좌담회알바좌담회카페\n26.08.20.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
