      "location": "",
      "type": "좌담회",
      "raw_content": "# # 자녀 양육 근로자 부모 대상 좌담회\n저희는 한국보건사회연구원의 의뢰를 받아 「일·돌봄 균형을 위한 자녀양육 근로자 부모 대상 FGI」를 진행하고 있습니다.\n본 조사는 자녀를 양육하는 근로자의 일·돌봄 균형 실태 및 제도 수요 등을 파악하여 현 제도의 한계를 발굴하고 맞춤형 육아 지원을 위한 정책 수립의 기초 자료를 확보하는데 목적이 있습니다.\n해당 좌담회에 관심이 있으신 분들께서는 하단의 링크를 통해 좌담회 신청 부탁드립니다.\n*대상: 초등학교 2학년 이하의 자녀가 있는 근로자\n*조건:\n조건 1 근로 조건 – 특수 형태 근로자 / 플랫폼 종사자\n조건 2 근로 조건 – 자영업자 / 사업주\n조건 3 근로 조건 – 고용 형태 이동 경험자 (계약직 > 정규직 등)\n*일시: 8/26~9/6 (주말 포함), 2시간 내외 진행\n*조사방법: 비대면(zoom)으로 진행\n*답례비: 10만원\n<신청 방법>\n대상자 선정 설문 링크입니다. (인원이 차면 선착순 마감이 될수도 있고, 조건에 맞지 않는 대상자일 경우 설문이 종료될 수 있습니다)\nhttps://survey.randr.co.kr/SurveyInOut/SurveyIn.aspx?cl=R1003&sid=15FBDF9442EF462F8A0FB52456F3F0EC\n글 탐색\n주방용 소형 가전 집방문 인터뷰",
